using UnityEngine;

namespace KingLastPiece
{
    /// <summary>
    /// References to authored effect assets (NamuFX slash prefabs, crack decals) so runtime code can spawn them.
    /// Lives at Resources/FxLibrary.asset; generated by KING ▸ Setup ▸ Effects Assets.
    /// </summary>
    [CreateAssetMenu(menuName = "KING/Fx Library", fileName = "FxLibrary")]
    public class FxLibrary : ScriptableObject
    {
        [Header("NamuFX Simple Stylized Slash vol2")]
        public GameObject slashA;
        public GameObject slashB;
        public GameObject slashC;
        public GameObject slashD;
        public GameObject slashInk;
        public GameObject slashWater;
        public GameObject slashAoeA;

        [Header("Tazo FX")]
        public GameObject recoverHold;   // the King's healing aura (looping)

        [Header("Ground cracks (URP decals)")]
        public Material crackDecal;
        public Texture2D[] crackTextures;

        static FxLibrary instance;
        static bool loaded;

        public static FxLibrary Instance
        {
            get
            {
                if (!loaded)
                {
                    loaded = true;
                    instance = Resources.Load<FxLibrary>("FxLibrary");
                }
                return instance;
            }
        }
    }
}
